export function visitsOf(log: Visit[], boat: string, latest?: number): Visit[] {
    const visits = log.filter((v) => v.boat === boat);
    if (latest === undefined) {
        return visits;
    }
    // `record` puts each new visit at the front of the log, so the front holds the most recently recorded.
    return visits.slice(0, Math.max(0, latest));
}
